import json,glob,re,collections,os
BASE='/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory'
recs=[]
for f in sorted(glob.glob(BASE+'/raw/*.json')):
    for x in json.load(open(f)):
        x['_f']=f.split('/')[-1][:-5]; recs.append(x)
byid={x['id']:x for x in recs}
kw=re.compile(r"\b(audio|sound|sounds|volume|loudness|lufs|dbtp|true peak|normali[sz]e|enhance voice|enhance_voice|match audio|match_audio|voice isolation|isolat|noise reduction|denois|hum\b|mains|gate pauses|noise gate|\bgate\b|de-?ess|sibilan|\beq\b|equali[sz]|leveller|ride the level|compressor|limiter|voice effect|duck|detach|attach audio|j-cut|l-cut|mute|solo|\bpan\b|mono|crossfade|fade|waveform|meter|scrub|synchroni[sz]e|sync\b|channels?\b|track mix|stems?\b|microphone)",re.I)
def text(x): return ' '.join([x['name'],x['what'],' '.join(x['ui']),' '.join(x['mcp']),' '.join(map(str,x['details']))])
def fmt(x):
    return f"{x['id']} [{x['area']}] {x['name']} :: {x['what']} | ui={'; '.join(x['ui'])} | mcp={','.join(x['mcp'])} | req={','.join(x['requires'])} | det={' ; '.join(map(str,x['details']))} | ev={x['evidence']}"

import sys; sys.path.insert(0,'/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory/work')
from audio_load import *
def c1(x):
    ev=x['evidence'].split(' ')[0].replace('docs/guide/audio.md:','').replace('app/Sources/','').replace('core/src/','')
    return f"{x['id'].replace('guide-audio-','G').replace('code-audio-','C')} {x['name']} :: {x['what']} | ui={'; '.join(x['ui'])} | mcp={','.join(x['mcp'])} | det={' ; '.join(map(str,x['details']))} | {ev}"
for name in ['guide-audio','code-audio']:
    with open(BASE+f'/work/{name}.txt','w') as f:
        for x in recs:
            if x['_f']==name: f.write(c1(x)+'\n')
    print(name, os.path.getsize(BASE+f'/work/{name}.txt'))

