import sys; sys.path.insert(0,'/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory/work')
from audio_load import *
t=json.load(open(BASE+'/taxonomy.json'))
for s in t['sections']:
    if s['id']=='audio': continue
    print(s['id'],':',' '.join(p['slug'].split('/',1)[1] for p in s['pages']))
def c2(x,n=230):
    d=' ; '.join(map(str,x['details']))
    ev=x['evidence'].split(' ')[0].replace('app/Sources/','').replace('core/src/','').replace('docs/guide/','')
    s=f"{x['id']} {x['name']} :: {x['what']} | {'; '.join(x['ui'])[:70]} | {','.join(x['mcp'])[:50]} | {d[:n]} | {ev}"
    return s
seen=lambda x:x['_f'] in('guide-audio','code-audio')
a=[x for x in recs if x['area']=='audio' and not seen(x)]
with open(BASE+'/work/rest_audio.txt','w') as f:
    for x in a: f.write(c2(x)+'\n')
o=[x for x in recs if x['area']!='audio' and not seen(x) and kw.search(x['name']+' '+' '.join(x['ui'])+' '+' '.join(x['mcp']))]
with open(BASE+'/work/rest_kw.txt','w') as f:
    for x in o: f.write(f"{x['id']} [{x['area']}] {x['name']} :: {x['what'][:130]} | {'; '.join(x['ui'])[:60]} | {','.join(x['mcp'])[:40]}\n")
o2=[x for x in recs if x['area']!='audio' and not seen(x) and x not in o and kw.search(text(x))]
with open(BASE+'/work/rest_kw2.txt','w') as f:
    for x in o2: f.write(f"{x['id']} [{x['area']}] {x['name']}\n")
print(len(a),len(o),len(o2))
for n in ['rest_audio','rest_kw','rest_kw2']: print(n,os.path.getsize(BASE+f'/work/{n}.txt'))

